import { createHmac, timingSafeEqual } from "node:crypto";
export type RunClaims = { agent: string; jira: string; run: string; exp: number; epoch: number };
export class RunTokenError extends Error {}
const SECRET = process.env.GATEWAY_SIGNING_KEY ?? "lab-only-signing-key";
const sign = (body: string) => createHmac("sha256", SECRET).update(body).digest();

export const signRunToken = (claims: RunClaims): string => {
  const body = Buffer.from(JSON.stringify(claims)).toString("base64url");
  return `${body}.${sign(body).toString("base64url")}`;
};

export const verifyRunToken = (header: string): RunClaims => {
  const [body = "", sig = ""] = header.replace(/^Bearer /, "").split(".");
  const want = sign(body);
  const got = Buffer.from(sig, "base64url");
  if (got.length !== want.length || !timingSafeEqual(got, want)) throw new RunTokenError("bad signature");
  const claims = JSON.parse(Buffer.from(body, "base64url").toString()) as RunClaims;
  if (claims.exp < Date.now() / 1000) throw new RunTokenError("expired");
  return claims;
};

import { createServer } from "node:http";
import { Readable, Transform } from "node:stream";
import { buffer } from "node:stream/consumers";
import { pipeline } from "node:stream/promises";
import type { ReadableStream } from "node:stream/web";
import { Agent } from "undici"; // 7.x, the engine inside Node 24's fetch; used only for the waits below
import { RunTokenError, verifyRunToken } from "./auth.js"; // HMAC token from the orchestrator: agent, jira, run, exp, epoch
import { workloadKey } from "./keys.js"; // Anthropic key per workload, from the ExternalSecret mount
import { Meter } from "./meter.js"; // usage counting (next ticket)

const ROUTES = new Set(["/v1/messages", "/v1/messages/count_tokens"]);
const FORWARD = ["anthropic-version", "anthropic-beta", "content-type", "accept"];
const RETURN = ["content-type", "request-id", "retry-after", "anthropic-ratelimit-requests-remaining"];
const upstream = new Agent({ connect: { timeout: 10_000 }, headersTimeout: 900_000, bodyTimeout: 900_000 }); // per wait, never a total

// Never refuses over budget: 429 and 529 pass through with retry-after, and the harness retries.

createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://gateway");
  if (req.method === "GET" && url.pathname === "/health") return void res.end("ok");
  if (req.method !== "POST" || !ROUTES.has(url.pathname)) return void res.writeHead(404).end();
  try {
    const claims = verifyRunToken(req.headers.authorization ?? ""); // RunTokenError if missing, expired or revoked
    const headers = Object.fromEntries(FORWARD.flatMap((h) => (req.headers[h] ? [[h, String(req.headers[h])]] : [])));
    const up = await fetch(`https://api.anthropic.com${url.pathname}${url.search}`, {
      method: "POST", body: await buffer(req), dispatcher: upstream, // no 1 MiB cap here: Anthropic caps request size itself
      headers: { ...headers, "x-api-key": workloadKey(claims.agent), "accept-encoding": "identity" }, // VM never sees the key
    });
    res.writeHead(up.status, Object.fromEntries(RETURN.flatMap((h) => { const v = up.headers.get(h); return v ? [[h, v]] : []; })));
    const meter = new Meter(claims, String(req.headers["x-ai-agents-step"] ?? "unknown"));
    const tap = new Transform({ transform(chunk: Buffer, _enc, done) { meter.feed(chunk); done(null, chunk); } }); // usage only
    await pipeline(up.body ? Readable.fromWeb(up.body as ReadableStream) : Readable.from([]), tap, res).finally(() => { meter.close(); });
  } catch (error) {
    if (!res.headersSent) res.writeHead(error instanceof RunTokenError ? 401 : 502).end();
  }
}).listen(8080); // access log (method, path, status, latency) only; no body is ever logged

