  if (req.method !== "POST" || req.url !== "/v1/messages") return void res.writeHead(404).end();
  res.writeHead(200, { "content-type": "text/event-stream", "request-id": "req_lab_1" });
  res.write(`event: message_start\ndata: ${start}\n\n`);
  res.write('event: content_block_delta\ndata: {"type":"content_block_delta","delta":{"type":"text_delta","text":"ok"}}\n\n');
  res.end(`event: message_delta\ndata: ${delta}\n\n`);
}).listen(8999, () => console.log("fake upstream on :8999"));

import { createServer } from "node:http";
import { Counter, register } from "@prometheus-io/client"; // prom-client's new name (same API)
import type { RunClaims } from "./auth.js";
import { pricePerMtok } from "./prices.js"; // gateway/prices.yaml: $ per million tokens by model and token type
const TOKENS = new Counter({ name: "ai_agents_llm_tokens_total", help: "Tokens through the gateway", labelNames: ["agent", "model", "type", "step"] });
const COST = new Counter({ name: "ai_agents_llm_cost_usd_total", help: "Estimated cost in USD", labelNames: ["agent", "model", "jira", "run", "step"] });
type Usage = { model?: string; usage?: Record<string, unknown>; message?: Usage };
export class Meter { // reads only the usage numbers of a Messages response; text is never kept or logged
  #model = "unknown"; #usage: Record<string, number> = {}; #buf = ""; #utf8 = new TextDecoder();
  constructor(readonly claims: RunClaims, readonly step: string) {}
  feed(chunk: Buffer): void {
    const events = (this.#buf + this.#utf8.decode(chunk, { stream: true })).split("\n\n"); // an SSE event ends with a blank line
    this.#buf = events.pop() ?? "";
    for (const line of events.flatMap((event) => event.split("\n"))) {
      if (line.startsWith("data: ") && line.includes('"usage"')) this.#take(JSON.parse(line.slice(6)) as Usage);
    }
  }

  #take(data: Usage): void {
    const msg = data.message ?? data; // message_start nests it; message_delta and plain JSON don't
    this.#model = msg.model ?? this.#model;
    const usage = msg.usage ?? {};
    for (const [k, v] of Object.entries(usage)) if (Number.isInteger(v)) this.#usage[k] = v as number;
    const hour = (usage.cache_creation as { ephemeral_1h_input_tokens?: number } | undefined)?.ephemeral_1h_input_tokens;
    if (Number.isInteger(hour)) this.#usage.cache_write_1h = hour as number; // 1-hour writes cost more than 5-minute ones
  }
  close(): void {
    if (this.#buf.trim().startsWith("{")) this.#take(JSON.parse(this.#buf) as Usage); // a non-streaming call: one JSON object
    const u = this.#usage, { agent, jira, run } = this.claims, labels = { agent, model: this.#model, step: this.step };
    const hour = u.cache_write_1h ?? 0, writes = u.cache_creation_input_tokens ?? 0;
    const parts = { input: u.input_tokens ?? 0, output: u.output_tokens ?? 0, cache_write_5m: writes - hour,
      cache_write_1h: hour, cache_read: u.cache_read_input_tokens ?? 0 };
    for (const [type, n] of Object.entries(parts)) TOKENS.inc({ ...labels, type: type.replace(/_(5m|1h)$/, "") }, n); // G1 reads type="cache_write"
    const cost = Object.entries(parts).reduce((sum, [type, n]) => sum + n * pricePerMtok(this.#model, type), 0) / 1_000_000;
    COST.inc({ ...labels, jira, run }, cost);
  }
}
